// Locate grey marks in the v1 shooting-screen PNGs. Reads files only.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/scan_png_v1.mjs
import { inflateSync } from 'node:zlib';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve } from 'node:path';

function readPng(file) {
  const data = readFileSync(file);
  const width = data.readUInt32BE(16);
  const height = data.readUInt32BE(20);
  const idat = [];
  for (let pos = 8; pos < data.length;) {
    const length = data.readUInt32BE(pos);
    const kind = data.toString('latin1', pos + 4, pos + 8);
    if (kind === 'IDAT') idat.push(data.subarray(pos + 8, pos + 8 + length));
    pos += 12 + length;
  }
  const raw = inflateSync(Buffer.concat(idat));
  const rows = [];
  for (let y = 0; y < height; y++) rows.push(raw.subarray((3 * width + 1) * y + 1, (3 * width + 1) * (y + 1)));
  return { width, height, rows };
}

function components(png, x0, y0, x1, y1, minCh) {
  const { width, rows } = png;
  const seen = new Uint8Array((x1 - x0) * (y1 - y0));
  const at = (x, y) => {
    const i = (x - x0) + (y - y0) * (x1 - x0);
    return seen[i];
  };
  const mark = (x, y) => { seen[(x - x0) + (y - y0) * (x1 - x0)] = 1; };
  const bright = (x, y) => {
    const p = y * width * 3 + x * 3;
    const r = rows[y][x * 3];
    const g = rows[y][x * 3 + 1];
    const b = rows[y][x * 3 + 2];
    return { r, g, b, on: r >= minCh || g >= minCh || b >= minCh };
  };
  const out = [];
  for (let y = y0; y < y1; y++) {
    for (let x = x0; x < x1; x++) {
      if (at(x, y) || !bright(x, y).on) continue;
      let minX = x, minY = y, maxX = x, maxY = y, n = 0;
      const sample = bright(x, y);
      const stack = [[x, y]];
      mark(x, y);
      while (stack.length) {
        const [cx, cy] = stack.pop();
        n += 1;
        if (cx < minX) minX = cx;
        if (cy < minY) minY = cy;
        if (cx > maxX) maxX = cx;
        if (cy > maxY) maxY = cy;
        for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const nx = cx + dx, ny = cy + dy;
          if (nx < x0 || ny < y0 || nx >= x1 || ny >= y1 || at(nx, ny) || !bright(nx, ny).on) continue;
          mark(nx, ny);
          stack.push([nx, ny]);
        }
      }
      out.push({ x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1, n, sample: [sample.r, sample.g, sample.b] });
    }
  }
  out.sort((a, b) => b.n - a.n);
  return out;
}

const files = ['obs-k1-v1-rest.png', 'obs-k1-v1-s1-held.png', 'obs-k1-v1-s1-up.png'];
const report = [];
for (const name of files) {
  const png = readPng(resolve('work/out', name));
  const mid = components(png, 300, 180, 600, 450, 20);
  const wide = components(png, 0, 80, png.width, 520, 40).slice(0, 12);
  report.push({ file: name, size: [png.width, png.height], centerMin20: mid.slice(0, 12), wideMin40: wide });
}
const rest = readPng(resolve('work/out/obs-k1-v1-rest.png'));
const held = readPng(resolve('work/out/obs-k1-v1-s1-held.png'));
let diff = 0;
let minX = rest.width, minY = rest.height, maxX = -1, maxY = -1;
for (let y = 0; y < rest.height; y++) {
  for (let x = 0; x < rest.width; x++) {
    const i = x * 3;
    if (rest.rows[y][i] !== held.rows[y][i] || rest.rows[y][i + 1] !== held.rows[y][i + 1] || rest.rows[y][i + 2] !== held.rows[y][i + 2]) {
      diff += 1;
      if (x < minX) minX = x;
      if (y < minY) minY = y;
      if (x > maxX) maxX = x;
      if (y > maxY) maxY = y;
    }
  }
}
report.push({
  compare: 'rest versus s1-held',
  changedPixels: diff,
  box: diff ? { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 } : null,
});
mkdirSync(resolve('work/out'), { recursive: true });
writeFileSync(resolve('work/out/scan-png-v1.json'), JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify(report, null, 2));
